import { SeedTsOauthTokenOptionalClient } from "../../src/Client";
import { mockServerPool } from "../mock-server/MockServerPool";
import { mockOAuthScheme } from "./mockAuth";

describe("AuthClient", () => {
    test("CreateOauth2Token", async () => {
        const server = mockServerPool.createServer();
        mockOAuthScheme(server);

        const client = new SeedTsOauthTokenOptionalClient({
            maxRetries: 0,
            clientId: "my_oauth_app_123",
            clientSecret: "sk_live_abcdef123456789",
            environment: server.baseUrl,
        });
        const rawRequestBody = {
            client_id: "my_oauth_app_123",
            client_secret: "sk_live_abcdef123456789",
            grant_type: "client_credentials",
        };
        const rawResponseBody = { access_token: "access_token", expires_in: 3600, refresh_token: "refresh_token" };

        server
            .mockEndpoint()
            .post("/v2/token")
            .formUrlEncodedBody(rawRequestBody)
            .respondWith()
            .statusCode(200)
            .jsonBody(rawResponseBody)
            .build();

        const response = await client.auth.createOauth2Token({
            client_id: "my_oauth_app_123",
            client_secret: "sk_live_abcdef123456789",
            grant_type: "client_credentials",
        });
        expect(response).toEqual(rawResponseBody);
    });
});
